pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, uint256 v, uint8 nTos) public {
        uint256 len = uint256(nTos);
        vm.assume(len > 0);

        BadCallee bad = new BadCallee();

        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = (i == 0) ? address(bad) : address(this);
        }

        bool ok;
        try c.transfer(from, address(c), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract BadCallee {
    fallback() external payable {
        revert("bad");
    }
